Chat gpt wrote me this plugin for inventory management. It works, I just have to Add and Remove characters manually which is not bad, just a bit more work
/*:
* @target MZ
* @plugindesc Separate inventories for different parties in RPG Maker MZ.
*
@Help
This plugin allows each party to have its own separate inventory,
* including gold, items, weapons, and armors.
*
* Plugin Commands:
* - SetPartyInventory partyId
*   Switches to the inventory for the specified party ID.
*
* @command SetPartyInventory
* @text Set Party Inventory
*
@desc
Switches to the inventory for the specified party ID.
*
* @arg partyId
* @type number
*
@min
1
*
@desc
The ID of the party you want to switch to.
*/
(() => {
const partyInventories = {};
const saveCurrentPartyInventory = (partyId) => {
partyInventories[partyId] = {
gold: $gameParty.gold(),
items: JSON.parse(JSON.stringify($gameParty._items)),
weapons: JSON.parse(JSON.stringify($gameParty._weapons)),
armors: JSON.parse(JSON.stringify($gameParty._armors))
};
};
const loadPartyInventory = (partyId) => {
const inventory = partyInventories[partyId];
if (inventory) {
$gameParty.gainGold(inventory.gold - $gameParty.gold());
$gameParty._items = JSON.parse(JSON.stringify(inventory.items));
$gameParty._weapons = JSON.parse(JSON.stringify(inventory.weapons));
$gameParty._armors = JSON.parse(JSON.stringify(inventory.armors));
} else {
// Initialize a new inventory if none exists for the party
partyInventories[partyId] = {
gold: 0,
items: {},
weapons: {},
armors: {}
};
loadPartyInventory(partyId);
}
};
PluginManager.registerCommand('SeparatePartyInventories', 'SetPartyInventory', args => {
const partyId = Number(args.partyId);
saveCurrentPartyInventory($gameParty._partyId);
loadPartyInventory(partyId);
$gameParty._partyId = partyId;
});
// Register the command in the plugin manager
PluginManager.registerCommand('SeparatePartyInventories', 'SetPartyInventory', args => {
const partyId = Number(args.partyId);
saveCurrentPartyInventory($gameParty._partyId);
loadPartyInventory(partyId);
$gameParty._partyId = partyId;
});
const _Game_Interpreter_pluginCommand = Game_Interpreter.prototype.pluginCommand;
Game_Interpreter.prototype.pluginCommand = function(command, args) {
_Game_Interpreter_pluginCommand.apply(this, arguments);
if (command === 'SetPartyInventory') {
const partyId = Number(args[0]);
saveCurrentPartyInventory($gameParty._partyId);
loadPartyInventory(partyId);
$gameParty._partyId = partyId;
}
};
})();

caethyril said:
Unless I've missed something, that code stores the data per-session, rather than per-playthrough: it is only initialised on boot, not on new game, and is not stored in save files. This means:
Recalling an inventory saved during the current session for a different playthrough is possible.
Attempting to load any inventory saved in a different session will fail.
