Thanks a bunch for pointing this out! Chat GPT revised the code to avoid that.
/*:
* @target MZ
* @plugindesc Separate inventories for each party with persistent storage.
*
@Author
YourName
*
*
@param
InventoryData
* @text Initial Inventory Data
* @type struct<Inventory>[]
*
@Default
[]
*
* @command SetPartyInventory
* @text Set Party Inventory
*
@desc
Set the inventory for a specific party ID.
*
* @arg partyId
* @text Party ID
* @type number
*
@Default
1
*
* @arg items
* @text Items
* @type string
*
@Default
""
*
* @command GetPartyInventory
* @text Get Party Inventory
*
@desc
Retrieve the inventory for a specific party ID.
*
* @arg partyId
* @text Party ID
* @type number
*
@Default
1
*
*
@Help
* This plugin allows you to manage separate inventories for different parties.
*
* Each party can have its own inventory, which is saved across playthroughs.
*/
(() => {
const parameters = PluginManager.parameters('SeparatePartyInventory');
const inventoryData = JSON.parse(parameters['InventoryData'] || "[]");
// Store inventories in a global variable
const inventories = {};
// Load inventories from saved data
const loadInventories = () => {
const savedData = StorageManager.loadObject('PartyInventories');
return savedData || {};
};
// Save inventories to local storage
const saveInventories = () => {
StorageManager.saveObject('PartyInventories', inventories);
};
// Initialize inventories
const initInventories = () => {
for (let i = 1; i <= 20; i++) { // Assuming a max of 20 parties
if (!inventories
) {
inventories
= {
items: {},
weapons: {},
armors: {}
};
}
}
};
// Command to set party inventory
PluginManager.registerCommand('SeparatePartyInventory', 'SetPartyInventory', args => {
const partyId = Number(args.partyId);
const items = JSON.parse(args.items);
inventories[partyId].items = items; // Save the items for the party
saveInventories(); // Save to local storage
});
// Command to get party inventory
PluginManager.registerCommand('SeparatePartyInventory', 'GetPartyInventory', args => {
const partyId = Number(args.partyId);
const inventory = inventories[partyId];
// Do something with the retrieved inventory, like displaying it
console.log(`Inventory for Party ${partyId}:`, inventory);
});
// Initialize on game start
const startGame = () => {
inventories = loadInventories(); // Load inventories when the game starts
initInventories(); // Initialize inventories if not set
};
// Call startGame function when the game starts
const _Scene_Boot_start = Scene_Boot.prototype.start;
Scene_Boot.prototype.start = function() {
_Scene_Boot_start.call(this);
startGame();
};
// Add an alias for saving the game
const _DataManager_makeSaveContents = DataManager.makeSaveContents;
DataManager.makeSaveContents = function() {
const contents = _DataManager_makeSaveContents.call(this);
contents.partyInventories = inventories; // Save inventories to game data
return contents;
};
// Add an alias for loading the game
const _DataManager_extractSaveContents = DataManager.extractSaveContents;
DataManager.extractSaveContents = function(contents) {
_DataManager_extractSaveContents.call(this, contents);
inventories = contents.partyInventories || {}; // Load inventories from game data
};
})();
